.art-ban-guide{--paper:#ffffff;--cream:#faf7f1;
    --ink:#1c1a15;--text:#514c41;
    --muted:#8b8574;
    --line:#ece6d9;--line-2:#ddd5c3;
    --gold:#9c7c3c;--gold-deep:#7c6127;
    --maxw:820px;}
.art-ban-guide .panel{background:var(--paper);border-radius:20px;overflow:hidden;border:1px solid var(--line);box-shadow:0 18px 48px -28px rgba(28,26,21,.28)}
.art-ban-guide .panel img{width:100%;height:auto;display:block;max-width:100%;object-fit:contain}
.art-ban-guide .article{margin-top:22px;background:var(--paper);border-radius:20px;border:1px solid var(--line);padding:34px 28px 40px;box-shadow:0 14px 40px -28px rgba(28,26,21,.22);text-align:center}
.art-ban-guide .article p{font-size:16.5px;color:#2a271f;margin:0 0 1.05em;line-height:1.85}
.art-ban-guide .article .tel{font-size:18px;font-weight:800;color:var(--ink);margin-top:18px}
@media(max-width:560px){.art-ban-guide .article{padding:26px 18px 32px}}

.art-classroom{--paper:#ffffff;--cream:#faf7f1;
    --ink:#1c1a15;--text:#514c41;
    --muted:#8b8574;
    --line:#ece6d9;--line-2:#ddd5c3;
    --gold:#9c7c3c;--gold-deep:#7c6127;
    --mark:#ffe56a;
    --sky:#5b9fd4;
    --maxw:820px;}
.art-classroom .panel{background:var(--paper);border-radius:20px;overflow:hidden;border:1px solid var(--line);box-shadow:0 18px 48px -28px rgba(28,26,21,.28)}
.art-classroom .panel img{width:100%;height:auto;display:block;max-width:100%;object-fit:contain}
.art-classroom .video{margin-top:22px;background:var(--paper);border-radius:20px;overflow:hidden;border:1px solid var(--line);box-shadow:0 14px 40px -28px rgba(28,26,21,.22)}
.art-classroom .video iframe{display:block;width:100%;aspect-ratio:16/9;border:0}
.art-classroom .video-link{padding:14px 18px 18px;text-align:center;font-size:14px;color:var(--muted)}
.art-classroom .video-link a{color:var(--gold-deep);font-weight:700;text-decoration:underline;text-underline-offset:3px}
.art-classroom .article{margin-top:22px;background:var(--paper);border-radius:20px;border:1px solid var(--line);padding:36px 28px 42px;box-shadow:0 14px 40px -28px rgba(28,26,21,.22);text-align:center}
.art-classroom .article p{font-size:16.5px;color:#2a271f;margin:0 0 .85em;line-height:1.85}
.art-classroom .mark{background:var(--mark);padding:0 .12em;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.art-classroom .sky{color:var(--sky);font-weight:800}
.art-classroom .head{font-size:clamp(18px,3.6vw,22px);font-weight:900;color:var(--ink);letter-spacing:-.03em;margin-bottom:6px}
.art-classroom .subhead{font-size:clamp(17px,3.2vw,20px);font-weight:800;color:var(--ink);margin-bottom:22px}
.art-classroom .checks{list-style:none;display:flex;flex-direction:column;gap:8px;margin:18px 0 22px;align-items:center}
.art-classroom .checks li{font-size:16.5px;font-weight:700;color:var(--ink)}
.art-classroom .pins{margin-top:22px}
.art-classroom .pins p{font-size:15.5px;margin:0 0 6px;color:var(--text)}
.art-classroom .blog-link{margin-top:18px;text-align:center;font-size:13.5px}
.art-classroom .blog-link a{color:var(--gold-deep);font-weight:700;text-decoration:underline;text-underline-offset:3px}
.art-classroom .awards{margin-top:22px;display:grid;grid-template-columns:1fr 1fr;gap:16px}
.art-classroom .award{background:var(--paper);border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 14px 40px -28px rgba(28,26,21,.22)}
.art-classroom .award img{width:100%;height:auto;display:block}
.art-classroom .award figcaption{padding:14px 16px 18px;text-align:center}
.art-classroom .award figcaption b{display:block;font-size:17px;font-weight:800;color:var(--ink)}
.art-classroom .award figcaption span{font-size:14px;color:var(--muted);font-weight:600}
.art-classroom .award figcaption em{font-style:normal;color:var(--gold-deep);font-weight:800}
@media(max-width:560px){.art-classroom .awards{grid-template-columns:1fr}
.art-classroom .article{padding:28px 18px 34px}}

