.art-jungwon .lead p:last-child{margin-bottom:0}
.art-jungwon .em{font-weight:800;color:var(--ink)}
.art-jungwon .mark{background:var(--mark);padding:0 .12em;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.art-jungwon .hook{margin:28px 0 8px;padding:22px 18px;text-align:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.art-jungwon .hook p{font-size:clamp(18px,3.4vw,22px);font-weight:800;color:var(--wine);letter-spacing:-.03em;line-height:1.45}
