.art-jungwon .reasons .num{display:inline-flex;align-items:center;justify-content:center;min-width:28px;height:28px;border-radius:999px;background:var(--wine);color:#fff;font-size:13px;font-weight:800;margin-right:8px;vertical-align:middle}
