.art-jungwon .process{margin-top:36px;padding-top:8px}
.art-jungwon .steps{list-style:none;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.art-jungwon .steps li{background:linear-gradient(180deg,#fff,var(--cream));border:1px solid var(--line);border-radius:18px;padding:20px 16px 18px;text-align:center}
.art-jungwon .steps .kicker{display:inline-block;font-size:11.5px;font-weight:800;letter-spacing:.16em;color:var(--gold);margin-bottom:8px}
.art-jungwon .steps h3{font-size:16.5px;font-weight:800;color:var(--ink);letter-spacing:-.03em;margin-bottom:8px;line-height:1.4}
.art-jungwon .steps p{font-size:14.5px;color:#3a362d;line-height:1.75;text-align:left}
.art-jungwon .steps .flow{display:none;background:none;border:0;padding:0}
.art-jungwon .closing{margin-top:32px;padding:24px 22px 22px;background:var(--wine-soft);border-radius:18px}
.art-jungwon .closing p{font-size:16.5px;color:#2a271f;line-height:1.9;margin:0 0 .85em}
.art-jungwon .closing p:last-child{margin-bottom:0;font-weight:700;color:var(--ink)}
