.art-jungheung .reasons li{padding:18px 16px 16px}
.art-jungheung .closing{padding:20px 16px}}
.art-jungheung .sec-title{font-size:19px;font-weight:900;color:var(--ink);letter-spacing:-.03em;margin:34px 0 4px}
.art-jungheung .sec-sub{font-size:14.5px;color:var(--muted);margin-bottom:6px}
.art-jungheung .pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0 6px}
.art-jungheung .pair figure{margin:0;background:var(--cream);border:1px solid var(--line);border-radius:16px;overflow:hidden}
.art-jungheung .pair img{width:100%;height:auto}
.art-jungheung .pair figcaption{padding:12px 14px 14px;font-size:14.5px;line-height:1.7;color:#3a362d}
.art-jungheung .pair figcaption b{display:block;color:var(--ink);font-size:15.5px;margin-bottom:2px}
.art-jungheung .hits{list-style:none;margin:16px 0 4px;border:1px solid var(--line);border-radius:16px;overflow:hidden}
.art-jungheung .hits li{display:grid;grid-template-columns:150px 1fr;gap:12px;padding:12px 16px;border-top:1px solid var(--line);font-size:15px;line-height:1.6}
.art-jungheung .hits li:first-child{border-top:0}
.art-jungheung .hits li:nth-child(odd){background:var(--cream)}
.art-jungheung .hits b{color:var(--wine)}
.art-jungheung .steps.four{grid-template-columns:repeat(2,1fr)}
.art-jungheung .tags{margin:14px 0 0;display:flex;flex-wrap:wrap;gap:6px}
.art-jungheung .tags span{font-size:13.5px;font-weight:700;background:var(--wine-soft);color:var(--wine);padding:4px 10px;border-radius:999px}
@media(max-width:720px){.art-jungheung .pair{grid-template-columns:1fr}
.art-jungheung .hits li{grid-template-columns:1fr;gap:2px}
.art-jungheung .steps.four{grid-template-columns:1fr}}
.art-jungheung .gallery{display:grid;grid-template-columns:repeat(var(--cols,2),1fr);gap:12px;margin:16px 0 6px}
.art-jungheung .gallery figure{margin:0;background:var(--cream);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.art-jungheung .gallery img{width:100%;height:auto;background:#fff}
.art-jungheung .gallery figcaption{padding:10px 12px;font-size:14px;font-weight:700;color:var(--ink);text-align:center}
.art-jungheung .gallery a{display:block}
.art-jungheung .gallery.docs img{aspect-ratio:3/4;object-fit:cover;object-position:top}
@media(max-width:720px){.art-jungheung .gallery{gap:8px}
.art-jungheung .gallery figcaption{font-size:12.5px;padding:8px 6px}}
